{"command":"python3 - <<'PY'
import subprocess, pty, os, time, select

def run(args, timeout=5):
    try:
        p=subprocess.run(["./executable"]+args, capture_output=True, timeout=timeout)
        print(f"ARGS {args} exit={p.returncode} stdout={p.stdout!r} stderr={p.stderr!r}")
    except subprocess.TimeoutExpired as e:
        print(f"ARGS {args} TIMEOUT stdout={e.stdout!r} stderr={e.stderr!r}")
def run_pty(args, timeout=5):
    pid, fd = pty.fork()
    if pid==0:
        os.execv("./executable", ["./executable"]+args)
    else:
        out=b""
        start=time.time()
        status=None
        while time.time()-start<timeout:
            r,_,_=select.select([fd],[],[],0.3)
            if r:
                try: data=os.read(fd,8192)
                except: break
                if not data: break
                out+=data
            wpid,st=os.waitpid(pid, os.WNOHANG)
            if wpid==pid:
                status=st
                # drain
                while True:
                    r,_,_=select.select([fd],[],[],0.2)
                    if not r: break
                    try: data=os.read(fd,8192)
                    except: break
                    if not data: break
                    out+=data
                break
        else:
            import signal; os.kill(pid, signal.SIGKILL)
        print(f"PTY ARGS {args} status={status} exit={os.waitstatus_to_exitcode(status) if status is not None else '?'} out={out!r}")

# exit codes for failure modes
for a in [["nonexistent.invalid"], ["-"], ["--","-h"], ["256.256.256.256"], [""], ["a b"], ["127.999.0.1"]]:
    run(a)
print("---pTY parse errors")
for a in [["--unknown"],["-x"],["-c"],["-c","abc","localhost"],["-h"],["-V"],[],["a","b"]]:
    run_pty(a)
print("---non tty parse errors")
for a in [["--unknown"],["-x"],["-c"],["-c","abc","localhost"],[],["a","b"],["-c=abc","localhost"],["-c","1.5","localhost"],["-c","9999999999999999999","localhost"],["-c","-1","localhost"],["-c","0","localhost"]]:
    run(a, timeout=4)
