{"command":"python3 - <<'PY'
import pty, os, select, fcntl, termios, struct, subprocess
def run(cols, stdin_tty=True, stdout_tty=True, stderr_tty=False):
    master=None
    def make():
        m,s=pty.openpty(); fcntl.ioctl(s, termios.TIOCSWINSZ, struct.pack("HHHH",24,cols,0,0)); return m,s
    masters=[]
    stdins=subprocess.DEVNULL; stdouts=subprocess.PIPE; stderrs=subprocess.PIPE
    m_in=s_in=m_out=s_out=m_err=s_err=None
    if stdin_tty: m_in,s_in=make(); stdins=s_in; masters.append(m_in)
    if stdout_tty: m_out,s_out=make(); stdouts=s_out; masters.append(m_out)
    if stderr_tty: m_err,s_err=make(); stderrs=s_err; masters.append(m_err)
    p=subprocess.Popen(["./executable","-h"], stdout=stdouts, stderr=stderrs, stdin=stdins)
    for s in [s_in,s_out,s_err]:
        if s is not None: os.close(s)
    out=b""; err=b""
    if stdout_tty:
        while True:
            r,_,_=select.select([m_out],[],[],2)
            if not r:break
            try:d=os.read(m_out,8192)
            except:break
            if not d:break
            out+=d
    else:
        out=p.stdout.read() if p.stdout else b""
    if not stderr_tty and p.stderr:
        try: err=p.stderr.read()
        except: pass
    p.wait()
    for m in masters:
        try:os.close(m)
        except:pass
    print(f"cols={cols} stdin_tty={stdin_tty} stdout_tty={stdout_tty} stderr={stderr_tty}")
    print(out.decode(errors='replace'))
    print("---")
for cols in [40,80]:
    run(cols,True,True)
    run(cols,False,True)
    run(cols,True,False)
    run(cols,False,False)
    run(cols,False,False,True)
PY
"}

