    def make():
        m,s=pty.openpty(); fcntl.ioctl(s,termios.TIOCSWINSZ,struct.pack("HHHH",24,cols,0,0)); return m,s
    m_in=s_in=m_out=s_out=m_err=s_err=None
    stdin=subprocess.DEVNULL; stdout=subprocess.PIPE; stderr=subprocess.PIPE
