    if stdout_tty: readers[m_out]='o'
    elif p.stdout: readers[p.stdout.fileno()]='o'
    if stderr_tty: readers[m_err]='e'
    elif p.stderr: readers[p.stderr.fileno()]='e'
    while readers:
